<div class="admin-panel"><div class="admin-panel__body grid gap-5 md:grid-cols-2"><div><label class="admin-label">Course</label><select id="assignment_course_id" name="course_id" class="admin-input" required><option value="">Select course</option>@foreach($courses as $course)<option value="{{ $course->id }}" @selected(old('course_id',$assignment->course_id)==$course->id)>{{ $course->name }}</option>@endforeach</select></div><div><label class="admin-label">Specific student</label><select id="assignment_enrolment_id" name="enrolment_id" class="admin-input" required><option value="">Select a student</option>@foreach($enrolments as $enrolment)<option value="{{ $enrolment->id }}" data-course="{{ $enrolment->course_id }}" @selected(old('enrolment_id',$assignment->enrolment_id)==$enrolment->id)>{{ $enrolment->studentProfile?->user?->name }} — {{ $enrolment->course?->name }}</option>@endforeach</select><p class="mt-1 text-xs text-[var(--admin-text-muted)]">Only this student will receive the assignment.</p></div><div><label class="admin-label">Due date and time</label><input type="datetime-local" name="due_at" class="admin-input" value="{{ old('due_at',$assignment->due_at?->format('Y-m-d\TH:i')) }}"></div><div class="md:col-span-2"><label class="admin-label">Assignment title</label><input name="title" class="admin-input" value="{{ old('title',$assignment->title) }}" required></div><div class="md:col-span-2"><label class="admin-label">Instructions</label><textarea name="instructions" rows="6" class="admin-input">{{ old('instructions',$assignment->instructions) }}</textarea></div><div class="md:col-span-2"><label class="admin-label">Assignment file</label><input type="file" name="attachment" class="admin-input">@if($assignment->attachment_path)<p class="mt-1 text-xs">{{ basename($assignment->attachment_path) }}</p>@endif</div><label class="admin-check md:col-span-2"><input type="checkbox" name="allow_resubmission" value="1" @checked(old('allow_resubmission',$assignment->allow_resubmission))> Allow students to replace their submission</label></div></div><script>document.addEventListener('DOMContentLoaded',()=>{const c=document.getElementById('assignment_course_id'),s=document.getElementById('assignment_enrolment_id');const filter=()=>{[...s.options].forEach((o,i)=>{if(i)o.hidden=!!c.value&&o.dataset.course!==c.value});if(s.selectedOptions[0]?.hidden)s.value=''};c.addEventListener('change',filter);filter()});</script>
